// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.concurrent.ConcurrentHashMap;

/**
 * The fastest wall-clock time each physical strategy has ever demonstrated for a query shape, in the current regime.
 * <p>
 * <b>Why this exists.</b> {@link LmdbNativeCostPosteriorStore} models a smoothed central estimate of log runtime: a
 * single fast run is Huber-clipped toward the running mean, its weight decays, and within a few dispatches the arm is
 * quoted at roughly what its runs average to. That is the correct thing to do when the question is "how long will this
 * take next time", and the wrong thing when the question is "which of these strategies is capable of answering this
 * query fastest". A strategy that has answered a query in 100 ms has proved a fact about itself; averaging a later 300
 * ms run into that fact throws the proof away. The measured consequence was a query settling permanently on
 * {@code packedFtreeAggregate} after the Janino-compiled parallel aggregate kernel had already run it twice as fast.
 * <p>
 * <b>The asymmetry is deliberate.</b> A faster run is believed immediately and kept; a slower run of an arm that has
 * already demonstrated a better time is discarded outright. Two things follow that callers must respect. Only a full,
 * non-probe execution may be offered here — a LIMIT-truncated close measures a fraction of the answer and a bounded
 * probe stops at its private row buffer, so latching either would pin a floor the arm cannot actually deliver, and
 * because the latch only ever moves downward that mispricing would never be corrected. And because a latched arm
 * exceeds its own predictive bound on every ordinary run, the severe-miss quarantine must be suppressed for it, or the
 * latch would delete the arm it exists to protect ({@link LmdbNativeAdaptiveCostModel#recordCompleted}).
 * <p>
 * <b>Staleness.</b> Entries are qualified by regime epoch. The {@link LmdbNativeCostPosteriorStore.ExactKey} already
 * carries the {@link LmdbNativeRegimeKey}; the epoch additionally covers within-regime shifts the tracker detects
 * (adjacency store publishing, a data-generation bump, drift). A best recorded under an older epoch reads as absent, so
 * a time proved against different data can never pin a price against the new data.
 * <p>
 * This state is in-memory only and is deliberately not persisted with the posteriors: a demonstrated time is cheap to
 * re-earn (one execution per arm) and a floor restored from a sidecar written on different hardware would be a floor no
 * arm here can reach.
 */
final class LmdbNativeBestObservedLedger {

	/** Opt out with {@code -Drdf4j.lmdb.costModel.bestObserved=false}; pricing then reverts to the posterior mean. */
	static final String ENABLED_PROPERTY = "rdf4j.lmdb.costModel.bestObserved";

	/** Mirrors the posterior store's per-sub-population variant cap so the two cannot diverge in footprint. */
	private static final int MAX_ENTRIES = LmdbNativeCostPosteriorStore.MAX_VARIANTS_PER_SUBPOPULATION;

	private record Best(long nanos, long epoch) {
	}

	private final boolean enabled;
	private final ConcurrentHashMap<LmdbNativeCostPosteriorStore.ExactKey, Best> best = new ConcurrentHashMap<>();

	LmdbNativeBestObservedLedger() {
		this(!"false".equalsIgnoreCase(System.getProperty(ENABLED_PROPERTY)));
	}

	LmdbNativeBestObservedLedger(boolean enabled) {
		this.enabled = enabled;
	}

	boolean enabled() {
		return enabled;
	}

	/** The demonstrated best for this arm in this epoch, or 0 when it has never completed a full run under it. */
	long bestNanos(LmdbNativeCostPosteriorStore.ExactKey key, long epoch) {
		if (!enabled) {
			return 0L;
		}
		Best current = best.get(key);
		return current == null || current.epoch != epoch ? 0L : current.nanos;
	}

	/**
	 * Offers one full, non-probe execution. Latches when it beats the standing best, or whenever the standing best was
	 * proved under a different epoch — a superseded floor is replaced outright rather than compared against.
	 */
	void observe(LmdbNativeCostPosteriorStore.ExactKey key, long nanos, long epoch) {
		if (!enabled || nanos <= 0L) {
			return;
		}
		// Admission is checked before the merge rather than inside it: ConcurrentHashMap remapping functions must stay
		// simple and must not re-enter the map. A racing pair may overshoot the cap by the number of racing threads,
		// which is the same tolerance the posterior store's admission counter accepts.
		if (!best.containsKey(key) && best.size() >= MAX_ENTRIES) {
			return;
		}
		best.merge(key, new Best(nanos, epoch),
				(existing, candidate) -> existing.epoch != candidate.epoch || candidate.nanos < existing.nanos
						? candidate
						: existing);
	}

	int size() {
		return best.size();
	}
}
